"""Render the design catalog as a portable, searchable report with no network dependencies."""
import json, html, sys
from pathlib import Path

root=Path(__file__).resolve().parents[1]
catalog=json.loads((root/'docs/scenarios/wholesale-2000.json').read_text())
coverage=json.loads((root/'docs/scenarios/coverage.json').read_text())
out=Path(sys.argv[1])
release=sys.argv[2] if len(sys.argv)>2 else 'Implemented and tested locally; release verification pending.'
pr=sys.argv[3] if len(sys.argv)>3 else ''
esc=lambda s:html.escape(str(s),quote=True)
source_cards=''.join(f'<li><a href="{esc(s["url"])}" target="_blank" rel="noopener">{s["id"]} · {esc(s["name"])}</a><p>{esc(s["note"])}</p></li>' for s in coverage['sources'])
gap_rows=''.join(f'''<tr><td><b>{g['id']}</b><br><span class="tag">{g['priority']}</span></td><td><strong>{esc(g['title'])}</strong><p>{esc(g['current'])}</p></td><td>{esc(g['gap'])}</td><td>{esc(g['fix'])}<p class="status">{esc(g['status'])}</p></td></tr>''' for g in coverage['gaps'])
categories={}
for s in catalog['scenarios']: categories[s['category']]=categories.get(s['category'],0)+1
category_cards=''.join(f'<li><span>{esc(k)}</span><b>{v}</b></li>' for k,v in categories.items())
data=json.dumps({'scenarios':catalog['scenarios'],'coverage':coverage},ensure_ascii=False,separators=(',',':')).replace('</','<\\/')
template='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>iCash X · 2,000 deal scenarios</title>
<style>
:root{color-scheme:light;--ink:#17222b;--muted:#5c6871;--line:#dfe5e7;--accent:#0b645e;--paper:#f6f7f5}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.55 system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}a{color:var(--accent);text-underline-offset:3px}header{background:#132c30;color:white;padding:48px max(24px,calc((100vw - 1260px)/2));}header p{color:#c8dcda;max-width:850px}h1{font-size:clamp(30px,4vw,50px);line-height:1.1;letter-spacing:-1.5px;margin:12px 0 20px}h2{font-size:28px;letter-spacing:-.5px}h3{font-size:19px}p{margin:9px 0 16px}.eyebrow{font-size:12px;letter-spacing:2px;text-transform:uppercase;font-weight:700}.metrics{display:flex;flex-wrap:wrap;gap:34px;margin-top:28px}.metrics b{display:block;font-size:32px;line-height:1.2}.metrics span{color:#c8dcda;font-size:13px}nav{background:white;border-bottom:1px solid var(--line);position:sticky;top:0;z-index:4;display:flex;gap:8px;padding:12px max(16px,calc((100vw - 1260px)/2));overflow:auto}nav button,button{border:1px solid var(--line);border-radius:6px;background:white;color:var(--ink);font:inherit;padding:9px 15px;cursor:pointer;white-space:nowrap}nav button[aria-selected=true],button.primary{background:var(--accent);color:white;border-color:var(--accent)}button:hover{filter:brightness(.94)}button:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid #e5b34d;outline-offset:2px}main{max-width:1310px;margin:auto;padding:30px 24px 60px}.panel[hidden]{display:none}.box{background:white;border:1px solid var(--line);border-radius:10px;padding:24px;margin:20px 0}.intro{font-size:21px;max-width:1000px}.muted{color:var(--muted)}.notice{border-left:4px solid var(--accent);padding:15px 20px;background:#eaf3f0}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}.grid .box{margin:0}table{border-collapse:collapse;width:100%;background:white;font-size:14px}th,td{padding:16px;vertical-align:top;border-bottom:1px solid var(--line);text-align:left}th{background:#ecf0ed;font-size:12px;text-transform:uppercase;letter-spacing:.5px}td p{margin:9px 0;color:var(--muted)}.tablewrap{overflow:auto;border:1px solid var(--line);border-radius:8px}.compare{min-width:950px}.compare td:nth-child(2){width:29%}.compare td:nth-child(3){width:27%}.compare td:nth-child(4){width:36%}.tag{display:inline-block;border:1px solid var(--line);padding:2px 7px;border-radius:4px;font-size:11px;margin:7px 0;color:var(--muted)}.status{font-size:12px;font-weight:600;color:var(--accent)!important}.controls{display:grid;grid-template-columns:2fr 1fr 1fr;gap:12px}.controls label{font-size:12px;font-weight:650;color:var(--muted)}input,select{display:block;border:1px solid #bac6c8;background:white;color:var(--ink);padding:12px;border-radius:6px;font:inherit;width:100%;margin-top:5px}.resultsbar{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;margin:20px 0}.cases{display:grid;grid-template-columns:1fr;gap:10px}.case{border:1px solid var(--line);background:white;border-radius:8px}.case summary{padding:18px;cursor:pointer;display:grid;grid-template-columns:95px 1fr 185px;gap:16px;align-items:start;list-style:none}.case summary::-webkit-details-marker{display:none}.case summary:after{content:none}.case summary strong{font-size:17px}.case summary small{display:block;color:var(--muted);font-size:12px;margin-top:4px}.case .id{font-size:12px;font-weight:750;color:var(--accent)}.case .badge{font-size:12px;color:var(--muted);text-align:right}.case[open] summary{border-bottom:1px solid var(--line)}.casebody{padding:20px;display:grid;grid-template-columns:1fr 1fr;gap:22px}.casebody h4{margin:0 0 5px;font-size:12px;text-transform:uppercase;letter-spacing:.5px}.casebody p{margin:0 0 17px;font-size:14px}.paths{font-size:12px;word-break:break-all}.wide{grid-column:1/-1}.categories{list-style:none;padding:0;display:grid;grid-template-columns:1fr 1fr;gap:0 30px}.categories li{display:flex;justify-content:space-between;gap:20px;border-bottom:1px solid var(--line);padding:11px 0;font-size:14px}.sources li{padding:12px 0}.sources p{font-size:14px;color:var(--muted)}.example{counter-increment:example}.example h3:before{content:counter(example,decimal-leading-zero) "  ";color:var(--accent)}.steps{margin:0;padding-left:21px}.steps li{margin:10px 0}.footer{margin-top:30px;font-size:12px;color:var(--muted)}code{font-size:12px;word-break:break-all}.empty{padding:30px;background:white;text-align:center}.paging{display:flex;gap:10px;align-items:center}.callout{font-weight:650;color:var(--accent)}@media(max-width:750px){header{padding:32px 20px}.grid,.casebody,.categories{grid-template-columns:1fr}.controls{grid-template-columns:1fr}main{padding:20px 14px}.case summary{grid-template-columns:70px 1fr;gap:10px}.case .badge{grid-column:2;text-align:left}.metrics{gap:22px}.box{padding:19px}.wide{grid-column:auto}h2{font-size:24px}.tablewrap{margin:0 -4px}}@media print{nav,.controls,.resultsbar,button{display:none}.panel[hidden]{display:block}header{background:white;color:black;padding:20px}header p,.metrics span{color:#333}main{max-width:none}.casebody{display:block}.box,.case{break-inside:avoid}.compare{min-width:0;font-size:10px}th,td{padding:7px}.cases{display:none}}
</style></head><body>
<header><div class="eyebrow">CashFlowKey · iCash X 2.0 · November 12, 2026</div><h1>Every deal needs a next step.</h1><p>A 2,000-scenario operating specification for seller conversations, contracts, buyers, showings, inspections, title and money—compared with the current iCash X implementation.</p><div class="metrics"><div><b>2,000</b><span>scenario branches</span></div><div><b>400</b><span>distinct situations</span></div><div><b>40</b><span>categories</span></div><div><b>16</b><span>gap areas</span></div></div></header>
<nav aria-label="Report sections"><button data-tab="overview" aria-selected="true">What needs to change</button><button data-tab="catalog" aria-selected="false">Search 2,000 scenarios</button><button data-tab="playthrough" aria-selected="false">How deals play out</button><button data-tab="evidence" aria-selected="false">Research & validation</button></nav>
<main>
<section class="panel" id="overview"><h2>Automatic action should be the default.</h2><p class="intro">When the AI has current facts and authority, it should answer, negotiate within its limits, collect missing details, schedule permitted follow-ups and advance the existing workflow. A routine question should not become a generic “review” task.</p>
<div class="notice"><strong>The missing layer is specific recovery work.</strong> iCash already has seller offers, signing, buyer journeys, showing confirmation, title follow-ups and a deal supervisor. The remaining work is to turn each unresolved dependency into an executable action with a source, responsible party, deadline and expected result.</div>
<div class="grid" style="margin-top:20px"><div class="box"><h3>What can run automatically</h3><ul class="steps"><li>Answer known facts and collect one missing detail.</li><li>Make supported seller counteroffers under the saved formula.</li><li>Send an existing authorized package through the original delivery path.</li><li>Coordinate viewing availability and seek both parties’ confirmation.</li><li>Gather title documents, follow up and reconcile original provider receipts.</li><li>Continue independent deals while one specific step waits.</li></ul></div><div class="box"><h3>What still needs an actual event</h3><ul class="steps"><li>A party’s signature or consent to changed binding terms.</li><li>Seller or occupant permission for property access.</li><li>Verified escrow funds and independently checked payment instructions.</li><li>Title or legal resolution of disputed ownership and liens.</li><li>A customer’s choice to return a manually controlled deal to the bot.</li></ul><p class="muted">The AI should pursue these prerequisites and track the response. It cannot replace them with a success label.</p></div></div>
<div class="box"><h3>Focused fixes completed in this work</h3><ol class="steps"><li>Recognize combined requests such as “Send photos and property details” as one package request.</li><li>Keep proposed or confirmed visits from becoming a generic inactivity prompt.</li><li>Stop claiming viewing options exist when the buyer has not requested a visit.</li><li>Reject negative title suggestions such as “The deposit wasn’t received.”</li></ol><p class="status">@@RELEASE@@</p>@@PR@@<p class="muted">The four corrections do not implement all 2,000 scenarios. The broader work is identified below with its current evidence and concrete implementation target.</p></div>
<h2>Current implementation compared with the target</h2><p class="muted">P0 means a prerequisite for dependable autonomous deal progression. P1 means an additional workflow or presentation improvement. These are engineering priorities, not measured production failure counts.</p><div class="tablewrap"><table class="compare"><thead><tr><th>Area</th><th>Already present</th><th>Remaining gap</th><th>Required action</th></tr></thead><tbody>@@GAPS@@</tbody></table></div>
<div class="box"><h3>Implementation order</h3><ol class="steps"><li><strong>Buyer call handoff:</strong> completed call → exact supported intent → existing package, details or viewing worker.</li><li><strong>Routine blocker resolution:</strong> separate an answerable question from a real change to price, dates, deposit or legal terms.</li><li><strong>Title reply tasks:</strong> verified ordinary email → specific document or clarification request → tracked completion.</li><li><strong>Inspection and deadlines:</strong> access, inspector, payer, report, re-underwriting and expiring contractual options.</li><li><strong>Verified payments and jurisdiction coverage:</strong> authoritative integrations and approved state-specific rules.</li></ol></div></section>
<section class="panel" id="catalog" hidden><h2>Search all 2,000 scenarios</h2><p>Each of the 400 situations has five branches: current evidence, missing evidence, newer conflict, uncertain execution and an overdue checkpoint. Expand a result to see the AI action, UI state and next step.</p><div class="controls"><label>Search event, action, evidence or next step<input id="query" type="search" placeholder="Try: title, no agents, deposit, low offer…"></label><label>Category<select id="category"><option value="">All 40 categories</option></select></label><label>Workflow branch<select id="branch"><option value="">All five branches</option></select></label></div><div class="resultsbar"><strong id="count" aria-live="polite"></strong><div class="paging"><button id="prev">Previous</button><span id="page"></span><button id="next">Next</button></div><button id="download">Download scenario JSON</button></div><div class="cases" id="cases"></div><p class="footer">The displayed UI states are proposed behavioral mappings to existing surfaces. They are not a claim that every label or recovery action is live today.</p></section>
<section class="panel" id="playthrough" hidden><h2>How the software should play the deal</h2><p class="muted">These are illustrative future-state acceptance sequences. Current gaps are called out directly.</p><div class="grid">
<article class="box example"><h3>Seller says the offer is too low</h3><ol class="steps"><li>Recognize a price objection, not an opt-out or acceptance.</li><li>Use current ARV, repairs and fee to calculate the supported counteroffer.</li><li>Ask only what remains missing; preserve the offer version.</li><li>If accepted, collect signer/date/inspection details and send the exact authorized agreement.</li></ol><p><b>UI:</b> Negotiating → waiting for seller → agreement sent only after its delivery evidence.</p><p><b>Current:</b> Core seller counteroffer execution exists. Mixed replies and new evidence need the expanded scenarios.</p></article>
<article class="box example"><h3>Buyer calls and asks for photos</h3><ol class="steps"><li>Confirm the property and current authorized buyer package.</li><li>Save the request from the completed call to an exact buyer/deal source.</li><li>Queue the existing permitted package sender once.</li><li>After delivery, wait for a buyer decision or permitted due follow-up.</li></ol><p><b>UI:</b> Package requested → queued → accepted/delivered → waiting for buyer.</p><p><b>Gap:</b> Voice currently records requests for review; the post-call execution adapter still needs implementation.</p></article>
<article class="box example"><h3>Buyer wants to view the house</h3><ol class="steps"><li>Collect the buyer’s request and available seller/occupant slots.</li><li>Normalize date, AM/PM and timezone.</li><li>Ask both parties to confirm the same slot.</li><li>Track changes, attendance and the buyer’s next decision.</li></ol><p><b>UI:</b> Waiting for availability → proposed → confirmed → outcome recorded.</p><p><b>Current:</b> Two-party confirmation exists. This work corrects the generic stale-progress prompt and false availability fallback.</p></article>
<article class="box example"><h3>Inspection finds a foundation problem</h3><ol class="steps"><li>Capture the actual report and affected condition facts.</li><li>Recalculate the economics without altering signed terms.</li><li>Present only supported options under the agreed authority.</li><li>Obtain the necessary amendment or other authorized resolution before the deadline.</li></ol><p><b>UI:</b> Inspection report received → revised terms proposed → awaiting required agreement.</p><p><b>Gap:</b> A complete inspection task workflow is not established by the inspected code.</p></article>
<article class="box example"><h3>Title needs one missing document</h3><ol class="steps"><li>Verify the sender and correct title file.</li><li>Identify the exact document, owner and deadline.</li><li>Request it through the authorized secure route and send the original verified document once.</li><li>Track title’s acknowledgment and the next outstanding requirement.</li></ol><p><b>UI:</b> Waiting for entity document → document sent → title confirming receipt.</p><p><b>Gap:</b> Ordinary title messages still rely partly on review; extracting tasks is separate from automatically declaring title clear.</p></article>
<article class="box example"><h3>Buyer says the deposit was paid</h3><ol class="steps"><li>Record the claim without reserving the property.</li><li>Obtain the escrow’s authoritative receipt and match the file, amount and buyer.</li><li>Verify the signed assignment and full required cleared deposit.</li><li>Reserve only when the actual terms allow it; progress toward title and closing.</li></ol><p><b>UI:</b> Payment reported → verifying receipt → deposit confirmed → reserved.</p><p><b>Gap:</b> End-to-end automatic verification requires an authoritative receipt integration. A screenshot alone is not that evidence.</p></article></div></section>
<section class="panel" id="evidence" hidden><h2>Research, coverage and proof</h2><div class="box"><h3>What was inspected</h3><p>The current repository at <code>@@SHA@@</code>, seller offer and dialogue execution, buyer request and journey handlers, showing coordination, title confirmation and suggestion parsing, closing payment evidence, supervisor behavior and existing UI next-action functions.</p><p>A read-only production check on November 12 confirmed the supervisor and seller/buyer progression flags were enabled. The live package classifier reproduced the combined-request gap. This snapshot does not establish a closed deal or complete live coverage.</p><p><b>Local validation:</b> actual SQL seller/buyer request-to-delivery fixture, title suggestion fixtures, UI next-action fixtures, connected journey/closing fixtures and TypeScript. Final release checks and deployment status are stated in the release note above.</p></div><div class="notice">@@METHOD@@</div><div class="box"><h3>What each scenario contains</h3><p>Stable ID, situation, workflow branch, expected action, required evidence, existing UI surface, proposed state, next step, checkpoint, authority boundary, mapped source files, gap ID and validation status.</p><p>Internal five-minute checks are proposed scheduling targets, not seller response promises or permission to contact every five minutes. Contractual deadlines, contact cadence, timezone, opt-outs, Pause and actual funds always remain specific inputs.</p></div><h3>Category coverage</h3><ul class="categories">@@CATEGORIES@@</ul><h3>Research sources</h3><p class="muted">Retrieved November 12, 2026. Research establishes common problem classes. The 400 situations and their branches are authored engineering scenarios.</p><ol class="sources">@@SOURCES@@</ol></section>
<p class="footer">Prepared for CashFlowKey. This report is read-only and sends no messages, signs no documents and moves no funds.</p></main>
<script id="data" type="application/json">@@DATA@@</script><script>
const D=JSON.parse(document.getElementById('data').textContent),all=D.scenarios,gaps=Object.fromEntries(D.coverage.gaps.map(g=>[g.id,g])),size=30;let page=0,filtered=all;
const $=id=>document.getElementById(id),e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
for(const name of [...new Set(all.map(s=>s.category))])$('category').add(new Option(name,name));
for(const name of [...new Set(all.map(s=>s.branch))])$('branch').add(new Option(name,name));
for(const b of document.querySelectorAll('[data-tab]'))b.addEventListener('click',()=>{for(const p of document.querySelectorAll('.panel'))p.hidden=p.id!==b.dataset.tab;for(const x of document.querySelectorAll('[data-tab]'))x.setAttribute('aria-selected',String(x===b));});
function apply(){const q=$('query').value.trim().toLowerCase(),cat=$('category').value,br=$('branch').value;filtered=all.filter(s=>(!cat||s.category===cat)&&(!br||s.branch===br)&&(!q||[s.id,s.event,s.action,s.requiredEvidence,s.nextStep,s.category,s.gap].join(' ').toLowerCase().includes(q)));page=0;render();}
function render(){const pages=Math.max(1,Math.ceil(filtered.length/size));page=Math.max(0,Math.min(page,pages-1));$('count').textContent=filtered.length.toLocaleString()+' matching scenarios';$('page').textContent=(page+1)+' / '+pages;$('prev').disabled=page===0;$('next').disabled=page>=pages-1;
$('cases').innerHTML=filtered.slice(page*size,(page+1)*size).map(s=>{const g=gaps[s.gap];return `<details class="case"><summary><span class="id">${e(s.id)}</span><span><strong>${e(s.event)}</strong><small>${e(s.category)}</small></span><span class="badge">${e(s.branch)}</span></summary><div class="casebody"><div><h4>Scenario condition</h4><p>${e(s.condition)}</p><h4>AI action</h4><p>${e(s.action)}</p><h4>Required evidence</h4><p>${e(s.requiredEvidence)}</p></div><div><h4>What the user sees</h4><p><b>${e(s.uiState)}</b><br>${e(s.uiSurface)}</p><h4>Next step</h4><p>${e(s.nextStep)}</p><h4>Checkpoint</h4><p>${e(s.checkpoint)}</p><h4>Authority</h4><p>${e(s.authority)}</p></div><div class="wide"><h4>Compared with current code · ${e(s.gap)}</h4><p>${e(g.current)} ${e(g.gap)}</p><p class="status">${e(g.status)}</p><div class="paths">${s.existingPaths.map(p=>`<a target="_blank" rel="noopener" href="https://github.com/richoffcashflow/iCash-X-2.0-/blob/${D.coverage.snapshot}/${encodeURI(p)}">${e(p)}</a>`).join(' · ')}</div><p class="footer">${e(s.validation)}. Research context: ${e(s.researchSource)}.</p></div></div></details>`;}).join('')||'<div class="empty">No matching scenarios. Try another term or clear a filter.</div>';}
for(const id of ['query','category','branch'])$(id).addEventListener(id==='query'?'input':'change',apply);
$('prev').onclick=()=>{page--;render()};$('next').onclick=()=>{page++;render()};$('download').onclick=()=>{const blob=new Blob([JSON.stringify(D,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='iCash-X-2000-Scenarios.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};render();
</script></body></html>'''
values={'RELEASE':esc(release),'PR':f'<p><a href="{esc(pr)}">View the implementation pull request</a></p>' if pr else '', 'GAPS':gap_rows,'CATEGORIES':category_cards,'SOURCES':source_cards,'DATA':data,'SHA':esc(coverage['snapshot']),'METHOD':esc(coverage['method'])}
for k,v in values.items():template=template.replace('@@'+k+'@@',v)
assert '@@' not in template
out.parent.mkdir(parents=True,exist_ok=True);out.write_text(template)
print(json.dumps({'path':str(out),'bytes':out.stat().st_size,'scenarios':len(catalog['scenarios'])}))
